    const show = (ids) => Array.from(ids, (i) => V.show(i)).join('');
    // 留出方式：6 个（动物, 问题）对 —— 每种问题 2 个；或者整种动物（熊猫、老虎）的全部 3 个问题
    const HOLD_PAIRS = [[4, 2], [7, 1], [3, 0], [0, 2], [5, 1], [6, 0]];
