    // SFT 配方（默认值 = 内嵌 checkpoint 的训练设置）
    const SFT = { T: 18, B: 4, steps: 400, warmup: 20, lr: 5e-4, minLR: 0.1, mix: 0.25, seed: 42, evalEvery: 20 };
