    const evalAt = (step) => (step < 20 ? [1, 2, 3, 5, 10, 15].includes(step) : step % 20 === 0);
    // 偏好候选：6 种回答类型 + 隐藏的「真实偏好」（模拟人类标注者心里的分数）
    const TYPES = ['正确', '张冠李戴', '事实错误', '答非所问', '啰嗦', '停不下来'];
    const TYPE_SHORT = ['正确', '张冠', '错值', '跑题', '啰嗦', '不停'];   // 热图列名用的两字简称
    const TYPE_TIP = ['标准答案', '说成另一只动物（SFT 最容易混淆的那只）', '主语对、事实错（最像真的那个错值）', '回答了另一个问题', '正确答案 + 一句没问的事实', '正确答案后不停，续写基座模型的「流水账」'];
    const R_TRUE = [2.0, -2.0, -2.0, -1.2, 0.8, -3.0];
