        const res = evalTF(st.m, st.exs);
        const agg = (sel) => { const r = res.filter((_, i) => sel(st.exs[i])); return { exact: LM.mean(r.map((x) => (x.exact ? 1 : 0))), p: LM.mean(r.map((x) => Math.exp(x.logp))), loss: LM.mean(r.map((x) => -x.logp / x.n)) }; };
        const tr = agg((e) => !e.held), he = agg((e) => e.held);
