        const val = set.slice(0, nVal), trn = set.slice(nVal);
        const ceil = val.filter(([, w, l]) => R_TRUE[w] > R_TRUE[l]).length / Math.max(1, val.filter(([, w, l]) => R_TRUE[w] !== R_TRUE[l]).length);
