            code: {
                title: 'C++ · Seq / Packed / pack / chatExample', src: `
                // 一条要打分 / 训练的对话：P = 提示 ⟨user⟩问题⟨bot⟩，R = 回答 …⟨eos⟩
                struct Seq { std::vector<int> P, R; };

                // 打包好的 batch：n 行，每行 T 个位置（展平成 n·T，与 gptForward 的输入相同）
                struct Packed {
                    std::vector<int> x;     // 输入 = 整条序列去掉最后一个 token；补齐的位置 = ⟨pad⟩（id 0）
                    std::vector<int> y;     // 目标 = 右移一位；只有「要预测回答 token」的位置有值，其余 = −1（crossEntropy / seqLogProb 跳过）
                    std::vector<int> rs;    // 这一行属于第几条序列（−1 = 不计）：seqLogProb 按它把每条回答的 log p 加起来
                    int T = 0, n = 0;
                };

                // 把 n 条对话补齐到同一长度 T（= 最长的一条减 1；Tfix > 0 时固定，SFT 用 T = 18）
                Packed pack(const std::vector<Seq>& seqs, int Tfix = 0) {
                    Packed pk;
                    pk.n = (int)seqs.size();
                    for (const Seq& s : seqs) pk.T = std::max(pk.T, (int)(s.P.size() + s.R.size()) - 1);
                    if (Tfix > 0) pk.T = Tfix;
                    int T = pk.T;
                    pk.x = ints(pk.n * T, 0);
                    pk.y = ints(pk.n * T, -1);
                    pk.rs = ints(pk.n * T, -1);
                    for (int b = 0; b < pk.n; b++) {
                        const Seq& s = seqs[b];
                        int np = (int)s.P.size(), n1 = np + (int)s.R.size();          // 问题长度、整条长度
                        for (int t = 0; t < T; t++) {
                            pk.x[b * T + t] = t < np ? s.P[t] : t < n1 - 1 ? s.R[t - np] : 0;
                            if (t >= np - 1 && t < n1 - 1) {                           // 从 ⟨bot⟩ 那一格起：预测回答的下一个 token（含 ⟨eos⟩）
                                pk.y[b * T + t] = s.R[t - np + 1];
                                pk.rs[b * T + t] = b;
                            }
                        }
                    }
                    return pk;
                }

                // 一条 SFT 样本：⟨user⟩问题⟨bot⟩回答⟨eos⟩ 补齐到 T 个位置；目标还在问题里的位置（和补齐的位置）y = −1
                Packed chatExample(const Example& e, int T) {
                    Seq s;
                    s.P = e.prompt;
                    s.R = e.resp;
                    std::vector<Seq> one = {s};
                    return pack(one, T);
                }`,
            },
