            code: {
                title: 'C++ · SFTConfig / sftBatch / sftTrain', src: `
                // SFT 配方（默认值 = 内嵌 checkpoint 的训练设置）
                struct SFTConfig {
                    int T = 18, B = 4, steps = 400, warmup = 20, seed = 42;
                    float lr = 5e-4f;       // 峰值学习率
                    float minLR = 0.1f;     // cosine 衰减到 0.1·lr
                    float mix = 0.25f;      // 每一行以这个概率换成一段预训练文本（对抗遗忘）
                };

                // 一个 B × T 的 SFT batch：预训练文本的行每个位置都算损失；对话的行只在回答部分有目标
                Batch sftBatch(const std::vector<Example>& train, const std::vector<int>& pre, const SFTConfig& c, Rng& r) {
                    int B = c.B, T = c.T;
                    Batch b;
                    b.x = ints(B * T, 0);
                    b.y = ints(B * T, -1);
                    for (int i = 0; i < B; i++) {
                        if (uniform(r) < c.mix) {                                      // 一段普通文本：y 是 x 右移一位
                            int s = (int)(uniform(r) * (pre.size() - T - 1));
                            for (int t = 0; t < T; t++) { b.x[i * T + t] = pre[s + t]; b.y[i * T + t] = pre[s + t + 1]; }
                            continue;
                        }
                        Packed one = chatExample(train[(int)(uniform(r) * train.size())], T);   // 一条对话：问题部分 y = −1
                        for (int t = 0; t < T; t++) { b.x[i * T + t] = one.x[t]; b.y[i * T + t] = one.y[t]; }
                    }
                    return b;
                }

                // SFT：从基座权重出发，在没留出的 18 个问答（+ 混入的预训练文本）上训练 400 步。
                // AdamW（β₂ = 0.95，不做权重衰减）· 20 步线性 warmup → cosine · 梯度裁剪到 1.0（在 trainStep 里）。losses 收集每一步的 loss
                GPT sftTrain(const GPT& base, const Vocab& tok, const std::vector<Example>& exs, const SFTConfig& c, std::vector<float>& losses) {
                    Rng rc = makeRng(2024);
                    std::vector<int> pre = encode(tok, worldCorpus(rc, 3000));         // 混入用的预训练语料（3000 句）
                    std::vector<Example> train;
                    for (const Example& e : exs) if (!e.held) train.push_back(e);       // 留出的问答不进 SFT 数据
                    GPT m = cloneGPT(base);
                    AdamW opt = makeAdamW(m.params, m.decay, c.lr, 0.f, 0.9f, 0.95f);
                    Rng r = makeRng(c.seed);
                    for (int step = 0; step < c.steps; step++) {
                        Batch b = sftBatch(train, pre, c, r);
                        float lr = cosineLR(step, c.lr, c.lr * c.minLR, c.warmup, c.steps);
                        losses.push_back(trainStep(m, opt, b, c.B, c.T, lr));          // 前向 → 交叉熵（y = −1 的位置忽略）→ 反向 → 裁剪 → AdamW
                    }
                    return m;
                }`,
            },
