                        PL.draw.plot(c, { x: [0, P06.GRPO_STEPS], y: [0.5, 1.1], xLabel: `GRPO 步数（${st.step} / ${P06.GRPO_STEPS}，G = ${st.G}）`, series: [{ data: ev.map(tr), x: xs, color: LM.C.train, width: 2, label: '训练过的问题' }, { data: ev.map(held), x: xs, color: LM.C.val, width: 2.5, label: '留出的问题' }], hmarks: [{ y: S.bi.refP[0], color: '#4a6f8a' }, { y: S.bi.refP[1], color: '#8a6a4a' }] });
